from pathlib import Path
p=Path('src/space.ts');s=p.read_text(encoding='utf-8');s=s.replace("async function exportRoom(){const atlas=new Image();atlas.src='/art/room-items.png';try{await atlas.decode();}","async function exportRoom(){const activity=getRoomActivity(room);const actor=new Image();actor.src='/art/ri-poses.png';const atlas=new Image();atlas.src='/art/room-items.png';try{await Promise.all([atlas.decode(),actor.decode()]);}")
needle="g.restore();}g.textAlign='left';g.fillStyle=room.palette"
replacement="g.restore();}if(room.activity&&activity.available){const col=activity.pose==='read'?1:activity.pose==='rest'?2:0;const row=activity.pose==='calm'?0:1;const cell=actor.naturalWidth/3;const x=160+(activity.slot%3)*300,y=260+Math.floor(activity.slot/3)*145;g.drawImage(actor,col*cell,row*cell,cell,cell,x-80,y-65,160,160);}g.textAlign='left';g.fillStyle=room.palette"
